# Let me analyze per-column for demo 2
print("Per-column analysis for demo 2:")
width = 27
for c in range(width):
    in_col = [demo2_input[r][c] for r in range(8)]
    out_col = [demo2_output[r][c] for r in range(8)]

    # Check if 8 in input leads to 8 in output (direct, one step down/up)
    changes = []
    for r in range(8):
        if in_col[r] == 8:
            # Did the 8 at this position exist in output?
            if out_col[r] != 8:
                # Check if 8 moved adjacent
                above = out_col[r-1] == 8 if r > 0 else False
                below = out_col[r+1] == 8 if r < 7 else False
                if above or below:
                    changes.append(f"(r={r}) 8->( Moved to adjacent )")
                else:
                    changes.append(f"(r={r}) 8->{out_col[r]}")

    if len(changes) > 0 or in_col != out_col:
        print(f"Column {c}:")
        for ch in changes[:4]:  # Show first 4 changes
            print(f"  {ch}")

# Check: for every 8 in output, is there an 8 in input at (r±1, c±1)?
height, width = 8, 27

def has_adjacent_8_in_input(r, c, input_grid):
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width:
                if input_grid[nr][nc] == 8:
                    return True
    return False

print("Checking if all output 8s are adjacent to input 8s:")
violations = []
for r in range(height):
    for c in range(width):
        if demo2_output[r][c] == 8 and not has_adjacent_8_in_input(r, c, demo2_input):
            violations.append((r, c))

print(f"Found {len(violations)} violations (output 8 without adjacent input 8)")
for r, c in violations[:20]:
    print(f"  (r={r}, c={c})")

