# Check if output rows are just input rows shifted
print("Checking output row = input row shifted:")

def positions_match(row1, row2):
    return set(row1) == set(row2)

for out_r in range(8):
    found = False
    for in_r in range(8):
        if positions_match(demo2_output[out_r], demo2_input[in_r]):
            if out_r != in_r:
                print(f"Output row {out_r} = Input row {in_r} (shifted by {in_r - out_r})")
            else:
                print(f"Output row {out_r} = Input row {in_r} (same)")
            found = True
            break
    if not found:
        print(f"Output row {out_r} has NO matching input row")

# More precise comparison of row content (not just positions)
print("Comparing output rows to input rows by exact content:")
for out_r in range(8):
    out_row = demo2_output[out_r]
    for in_r in range(8):
        in_row = demo2_input[in_r]
        if in_row == out_row:
            if in_r > 0:
                print(f"Output row {out_r} = Input row {in_r} (shifted by {in_r - out_r})")
print("Done checking")
